const readline = require('readline');
const rl = readline.createInterface({ input: process.stdin, output: process.stdout });

function readLine() {
    return new Promise(resolve => rl.on('line', line => resolve(line)));
}

async function main() {
    const [k, r] = (await readLine()).split(' ').map(Number);
    let i = 1;
    while (true) {
        if ((i * k) % 10 === 0 || (i * k - r) % 10 === 0) {
            console.log(i);
            break;
        }
        i++;
    }
    rl.close();
}

main();
